package com.liskovsoft.smartyoutubetv2.common.exoplayer.other;

import android.text.Html;

import java.util.ArrayList;
import java.util.List;

/**
 * Pulls the display texts out of a WebVTT file, in cue order, with the repeated lines of
 * autogenerated subtitles already stripped.<br/>
 * The result has to line up with the cues ExoPlayer hands to {@link SubtitleManager} while
 * playing, otherwise the prefetched translations are keyed differently and never hit. So this
 * deliberately mirrors what ExoPlayer does in {@code WebvttCueParser}: trim every line, join
 * them with {@code \n}, and then run {@code Html.fromHtml} over the whole cue -- that last step
 * both decodes entities ({@code &amp;} to {@code &}) and drops the tags it does not know
 * ({@code <c>}, inline timestamps).
 */
public class SubtitleVttParser {
    public static List<String> parse(String vtt) {
        List<String> result = new ArrayList<>();
        SubtitleTextDeduplicator deduplicator = new SubtitleTextDeduplicator();

        for (String cue : extractCues(vtt)) {
            // Same call ExoPlayer makes, so both sides see the exact same text.
            @SuppressWarnings("deprecation")
            String text = Html.fromHtml(cue).toString();
            String deduplicated = deduplicator.deduplicate(text);

            if (deduplicated != null && !deduplicated.trim().isEmpty()) {
                result.add(deduplicated);
            }
        }

        return result;
    }

    /**
     * Cue payloads in file order: lines trimmed and joined with {@code \n}, tags still in place.
     * Kept free of Android APIs so the structure can be unit tested on the JVM.
     */
    static List<String> extractCues(String vtt) {
        List<String> result = new ArrayList<>();

        if (vtt == null) {
            return result;
        }

        StringBuilder current = new StringBuilder();
        boolean insideCue = false;

        for (String rawLine : vtt.replace("\r\n", "\n").replace('\r', '\n').split("\n")) {
            if (rawLine.contains("-->")) {
                flush(result, current);
                insideCue = true;
                continue;
            }

            if (rawLine.trim().isEmpty()) {
                flush(result, current);
                insideCue = false;
                continue;
            }

            if (!insideCue) { // header or an optional cue identifier
                continue;
            }

            String line = rawLine.trim();

            if (current.length() > 0) {
                current.append('\n');
            }

            current.append(line);
        }

        flush(result, current);

        return result;
    }

    private static void flush(List<String> result, StringBuilder current) {
        if (current.length() > 0) {
            result.add(current.toString());
            current.setLength(0);
        }
    }
}
